import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25, C: 33.4, D: 0.1 }
const pricing = { priceOf: async (sku) => prices[sku] }

async function withApp(fn) {
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  const base = `http://localhost:${server.address().port}`
  try { await fn(base) } finally { server.close() }
}

async function totalFor(items) {
  let total
  await withApp(async (base) => {
    const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
    assert.equal(res.status, 201)
    total = (await res.json()).total
  })
  return total
}

// Characterization tests: pin current behaviour (10% off when raw total > 100, result floored).
const cases = [
  ['single item, no discount', [{ sku: 'A', qty: 1 }], 10],
  ['multiple lines are summed', [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }], 70],
  ['exactly 100 gets no discount', [{ sku: 'A', qty: 10 }], 100],
  ['just over 100 gets 10% off (100.1 -> 90.09 -> floor)', [{ sku: 'A', qty: 10 }, { sku: 'D', qty: 1 }], 90],
  ['101 -> 90.9 floored to 90 (not rounded to 91)', [{ sku: 'A', qty: 10 }, { sku: 'D', qty: 10 }], 90],
  ['large order 200 -> 180', [{ sku: 'A', qty: 20 }], 180],
  ['large order 250 -> 225', [{ sku: 'B', qty: 10 }], 225],
  ['fractional prices: 3*33.4=100.2 -> 90.18 -> 90', [{ sku: 'C', qty: 3 }], 90],
  ['very large order 1000 -> 900', [{ sku: 'A', qty: 100 }], 900],
  ['fractional undiscounted total is floored: 99.9 -> 99', [{ sku: 'C', qty: 2 }, { sku: 'A', qty: 3 }], 96],
]
for (const [name, items, expected] of cases) {
  test(name, async () => assert.equal(await totalFor(items), expected))
}

test('stored order total matches created total', async () => {
  await withApp(async (base) => {
    const created = await (await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items: [{ sku: 'A', qty: 20 }] }) })).json()
    const fetched = await (await fetch(`${base}/orders/${created.id}`)).json()
    assert.equal(fetched.total, 180)
  })
})

test('empty items rejected', async () => {
  await withApp(async (base) => {
    const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items: [] }) })
    assert.equal(res.status, 400)
  })
})
EOF
